//! Differential ratchet for `src/engine/battleScriptTrysetspikesOpcode.ts`.
//! Expected complete projected outputs, controls, operand/error ordering, and
//! immutable input behavior are generated by executing the canonical
//! TypeScript handler; regenerate with `node --experimental-strip-types
//! core-rs/tools/gen-battle-script-trysetspikes-vectors.mjs`.
//!
//! Behavioral source is `Cmd_trysetspikes` in
//! `reference/pokeemerald/src/battle_script_commands.c:8485-8500`, dispatched
//! as opcode `0xB0` at `:507`. Its macro is
//! `asm/macros/battle_script.inc:923-925`, concrete Spikes call is
//! `data/battle_scripts_1.s:1544-1549`, `SIDE_STATUS_SPIKES` is
//! `include/constants/battle.h:213`, and `SideTimer::spikesAmount` is the
//! source `u8` at `include/battle.h:149-162`. The canonical TypeScript state
//! deliberately preserves full `u32` side-status words at
//! `battleScriptRulesContext.ts:2711-2714`.

use std::collections::BTreeSet;

use factory_core::battle_script_trysetspikes::{
    apply_battle_script_trysetspikes, BattleScriptTrysetspikesBattler,
    BattleScriptTrysetspikesBattlerState, BattleScriptTrysetspikesBit,
    BattleScriptTrysetspikesControl, BattleScriptTrysetspikesInstruction,
    BattleScriptTrysetspikesOperand, BattleScriptTrysetspikesOutcome,
    BattleScriptTrysetspikesRoles, BattleScriptTrysetspikesRules, BattleScriptTrysetspikesSide,
    BattleScriptTrysetspikesSideTimerState, BATTLE_SCRIPT_SIDE_STATUS_SPIKES,
    BATTLE_SCRIPT_TRYSETSPIKES_BATTLERS, BATTLE_SCRIPT_TRYSETSPIKES_BATTLER_COUNT,
    BATTLE_SCRIPT_TRYSETSPIKES_FAILURE_POINTER_WIDTH_BYTES, BATTLE_SCRIPT_TRYSETSPIKES_OPCODE,
    BATTLE_SCRIPT_TRYSETSPIKES_SIDES, BATTLE_SCRIPT_TRYSETSPIKES_SIDE_COUNT,
};
use factory_core::battle_script_trysetspikes_vectors_gen::{
    BattleScriptTrysetspikesVectorCase, BattleScriptTrysetspikesVectorInstruction,
    BattleScriptTrysetspikesVectorSideTimer, BattleScriptTrysetspikesVectorState,
    BATTLE_SCRIPT_TRYSETSPIKES_ATTACKER_DOMAIN, BATTLE_SCRIPT_TRYSETSPIKES_BRANCH_CENSUS,
    BATTLE_SCRIPT_TRYSETSPIKES_CANONICAL_BATTLER_SIDES, BATTLE_SCRIPT_TRYSETSPIKES_CASES,
    BATTLE_SCRIPT_TRYSETSPIKES_CATEGORY_CENSUS, BATTLE_SCRIPT_TRYSETSPIKES_DOMAIN_CENSUS,
    BATTLE_SCRIPT_TRYSETSPIKES_SIDE_DOMAIN, BATTLE_SCRIPT_TRYSETSPIKES_SIDE_STATUS_U32_EDGE_DOMAIN,
    BATTLE_SCRIPT_TRYSETSPIKES_SPIKES_AMOUNT_U8_DOMAIN, BATTLE_SCRIPT_TRYSETSPIKES_U8_EDGE_DOMAIN,
    BATTLE_SCRIPT_TRYSETSPIKES_VECTOR_CORPUS_SHA256,
};

fn battler(value: u8) -> BattleScriptTrysetspikesBattler {
    match value {
        0 => BattleScriptTrysetspikesBattler::Battler0,
        1 => BattleScriptTrysetspikesBattler::Battler1,
        2 => BattleScriptTrysetspikesBattler::Battler2,
        3 => BattleScriptTrysetspikesBattler::Battler3,
        _ => panic!("generated battler must be 0..3, got {value}"),
    }
}

fn side(value: u8) -> BattleScriptTrysetspikesSide {
    match value {
        0 => BattleScriptTrysetspikesSide::Player,
        1 => BattleScriptTrysetspikesSide::Opponent,
        _ => panic!("generated side must be 0 or 1, got {value}"),
    }
}

fn bit(value: u8) -> BattleScriptTrysetspikesBit {
    match value {
        0 => BattleScriptTrysetspikesBit::Clear,
        1 => BattleScriptTrysetspikesBit::Set,
        _ => panic!("generated Pressure bit must be 0 or 1, got {value}"),
    }
}

fn timer(value: BattleScriptTrysetspikesVectorSideTimer) -> BattleScriptTrysetspikesSideTimerState {
    BattleScriptTrysetspikesSideTimerState {
        reflect_timer: value.reflect_timer,
        reflect_battler_id: battler(value.reflect_battler_id),
        lightscreen_timer: value.lightscreen_timer,
        lightscreen_battler_id: battler(value.lightscreen_battler_id),
        safeguard_timer: value.safeguard_timer,
        safeguard_battler_id: battler(value.safeguard_battler_id),
        mist_battler_id: battler(value.mist_battler_id),
        followme_timer: value.followme_timer,
        followme_target: battler(value.followme_target),
        spikes_amount: value.spikes_amount,
    }
}

fn vector_timer(
    value: BattleScriptTrysetspikesSideTimerState,
) -> BattleScriptTrysetspikesVectorSideTimer {
    BattleScriptTrysetspikesVectorSideTimer {
        reflect_timer: value.reflect_timer,
        reflect_battler_id: value.reflect_battler_id.as_u8(),
        lightscreen_timer: value.lightscreen_timer,
        lightscreen_battler_id: value.lightscreen_battler_id.as_u8(),
        safeguard_timer: value.safeguard_timer,
        safeguard_battler_id: value.safeguard_battler_id.as_u8(),
        mist_battler_id: value.mist_battler_id.as_u8(),
        followme_timer: value.followme_timer,
        followme_target: value.followme_target.as_u8(),
        spikes_amount: value.spikes_amount,
    }
}

fn rules(value: BattleScriptTrysetspikesVectorState) -> BattleScriptTrysetspikesRules {
    BattleScriptTrysetspikesRules {
        battlers: core::array::from_fn(|index| BattleScriptTrysetspikesBattlerState {
            side: side(value.battler_sides[index]),
            pp_not_affected_by_pressure: bit(value.pp_not_affected_by_pressure[index]),
        }),
        side_statuses: value.side_statuses,
        side_timers: value.side_timers.map(timer),
        mist_timers: value.mist_timers,
        selector_roles: BattleScriptTrysetspikesRoles {
            attacker: value.attacker,
            target: value.target,
            effect_battler: value.effect_battler,
            fainted: value.fainted,
        },
    }
}

fn vector_state(value: BattleScriptTrysetspikesRules) -> BattleScriptTrysetspikesVectorState {
    BattleScriptTrysetspikesVectorState {
        battler_sides: value.battlers.map(|battler| battler.side.as_u8()),
        pp_not_affected_by_pressure: value
            .battlers
            .map(|battler| battler.pp_not_affected_by_pressure.as_u8()),
        side_statuses: value.side_statuses,
        side_timers: value.side_timers.map(vector_timer),
        mist_timers: value.mist_timers,
        attacker: value.selector_roles.attacker,
        target: value.selector_roles.target,
        effect_battler: value.selector_roles.effect_battler,
        fainted: value.selector_roles.fainted,
    }
}

fn operands(
    value: BattleScriptTrysetspikesVectorInstruction,
) -> Vec<BattleScriptTrysetspikesOperand<'static>> {
    assert_eq!(
        value.operand_widths.len(),
        value.operand_expressions.len(),
        "generated operand width/expression arrays must agree",
    );
    value
        .operand_widths
        .iter()
        .copied()
        .zip(value.operand_expressions.iter().copied())
        .map(
            |(width_bytes, expression)| BattleScriptTrysetspikesOperand { width_bytes, expression },
        )
        .collect()
}

#[test]
fn complete_projected_outputs_controls_errors_and_input_immutability_match_canonical_typescript() {
    assert_eq!(BATTLE_SCRIPT_TRYSETSPIKES_CASES.len(), 1262);
    for (case_index, case) in BATTLE_SCRIPT_TRYSETSPIKES_CASES.iter().enumerate() {
        execute_case(case_index, case);
    }
}

fn execute_case(case_index: usize, case: &BattleScriptTrysetspikesVectorCase) {
    let input = rules(case.initial);
    let before = input;
    let mut current = input;
    let operands = operands(case.instruction);
    let instruction = BattleScriptTrysetspikesInstruction {
        operands: &operands,
        resolved_failure_target: case.instruction.resolved_failure_target,
    };
    let mut actual_controls = Vec::new();
    let mut actual_error = None;

    for application in 0..case.applications {
        let prior = current;
        match apply_battle_script_trysetspikes(instruction, &current) {
            Ok(outcome) => {
                actual_controls.push(outcome.control);
                assert_transition_shape(case_index, case, application, prior, outcome);
                current = outcome.rules;
            }
            Err(error) => {
                actual_error = Some(error.to_string());
                break;
            }
        }
    }

    assert_eq!(
        input, before,
        "case {case_index} {}: native transformation mutated input",
        case.label,
    );
    match (actual_error, case.expected, case.expected_error) {
        (None, Some(expected), None) => {
            assert_eq!(
                actual_controls.as_slice(),
                case.controls,
                "case {case_index} {}: canonical control sequence",
                case.label,
            );
            assert_eq!(
                actual_controls.len(),
                usize::from(case.applications),
                "case {case_index} {}: successful sequence stopped early",
                case.label,
            );
            assert_eq!(
                vector_state(current),
                expected,
                "case {case_index} {}: complete projected output",
                case.label,
            );
        }
        (Some(error), None, Some(expected_error)) => {
            assert_eq!(
                actual_controls.as_slice(),
                case.controls,
                "case {case_index} {}: error must not produce a control result",
                case.label,
            );
            assert_eq!(
                error, expected_error,
                "case {case_index} {}: exact canonical handler error",
                case.label,
            );
        }
        (error, expected, expected_error) => panic!(
            "case {case_index} {}: generated outcome shape disagrees with native result: error={error:?}, expected={expected:?}, expected_error={expected_error:?}",
            case.label,
        ),
    }
}

fn assert_transition_shape(
    case_index: usize,
    case: &BattleScriptTrysetspikesVectorCase,
    application: u8,
    prior: BattleScriptTrysetspikesRules,
    outcome: BattleScriptTrysetspikesOutcome,
) {
    let attacker = prior.selector_roles.attacker.unwrap_or_else(|| {
        panic!(
            "case {case_index} {} application {application}: successful result had no attacker",
            case.label,
        )
    });
    let attacker_side = prior.battlers[attacker.index()].side;
    let target_side = attacker_side.opposite();
    let target_index = target_side.index();
    let attacker_index = attacker_side.index();
    let amount = prior.side_timers[target_index].spikes_amount;

    assert_eq!(
        outcome.rules.selector_roles, prior.selector_roles,
        "case {case_index} {} application {application}: changed selector roles",
        case.label,
    );
    assert_eq!(
        outcome.rules.mist_timers, prior.mist_timers,
        "case {case_index} {} application {application}: changed mistTimer siblings",
        case.label,
    );

    match outcome.control {
        BattleScriptTrysetspikesControl::FailJump => {
            assert_eq!(
                amount, 3,
                "case {case_index} {} application {application}: fail jump must use exact amount == 3",
                case.label,
            );
            assert_eq!(
                outcome.rules.side_statuses, prior.side_statuses,
                "case {case_index} {} application {application}: failure changed side status words",
                case.label,
            );
            assert_eq!(
                outcome.rules.side_timers, prior.side_timers,
                "case {case_index} {} application {application}: failure changed side timer records",
                case.label,
            );
            for battler in BATTLE_SCRIPT_TRYSETSPIKES_BATTLERS {
                if battler == attacker {
                    assert_eq!(
                        outcome.rules.battlers[battler.index()].side,
                        prior.battlers[battler.index()].side,
                        "case {case_index} {} application {application}: failure changed attacker side",
                        case.label,
                    );
                    assert_eq!(
                        outcome.rules.battlers[battler.index()].pp_not_affected_by_pressure,
                        BattleScriptTrysetspikesBit::Set,
                        "case {case_index} {} application {application}: failure did not exempt attacker PP from Pressure",
                        case.label,
                    );
                } else {
                    assert_eq!(
                        outcome.rules.battlers[battler.index()],
                        prior.battlers[battler.index()],
                        "case {case_index} {} application {application}: failure changed sibling battler {}",
                        case.label,
                        battler.as_u8(),
                    );
                }
            }
        }
        BattleScriptTrysetspikesControl::Advance => {
            assert_ne!(
                amount, 3,
                "case {case_index} {} application {application}: advance accepted exact amount == 3",
                case.label,
            );
            assert_eq!(
                outcome.rules.battlers, prior.battlers,
                "case {case_index} {} application {application}: success changed any battler or Pressure bit",
                case.label,
            );
            assert_eq!(
                outcome.rules.side_statuses[attacker_index], prior.side_statuses[attacker_index],
                "case {case_index} {} application {application}: success changed attacker-side status word",
                case.label,
            );
            assert_eq!(
                outcome.rules.side_statuses[target_index],
                prior.side_statuses[target_index] | BATTLE_SCRIPT_SIDE_STATUS_SPIKES,
                "case {case_index} {} application {application}: success did not OR target-side Spikes bit",
                case.label,
            );
            assert_eq!(
                outcome.rules.side_timers[attacker_index], prior.side_timers[attacker_index],
                "case {case_index} {} application {application}: success changed attacker-side timer",
                case.label,
            );
            let mut expected_timer = prior.side_timers[target_index];
            expected_timer.spikes_amount = amount.wrapping_add(1);
            assert_eq!(
                outcome.rules.side_timers[target_index], expected_timer,
                "case {case_index} {} application {application}: success changed a target timer sibling or did not wrap amount",
                case.label,
            );
        }
    }
}

#[test]
fn full_u8_amount_domain_and_all_attacker_side_aliases_are_covered() {
    let full = BATTLE_SCRIPT_TRYSETSPIKES_CASES
        .iter()
        .filter(|case| case.category == "spikes-amount-u8-full-domain-by-attacker-side")
        .collect::<Vec<_>>();
    assert_eq!(full.len(), 512);
    for attacker_side in BATTLE_SCRIPT_TRYSETSPIKES_SIDE_DOMAIN {
        let amounts = full
            .iter()
            .filter_map(|case| {
                let attacker = case.initial.attacker?;
                (case.initial.battler_sides[attacker.index()] == attacker_side).then_some(
                    case.initial.side_timers[usize::from(attacker_side ^ 1)].spikes_amount,
                )
            })
            .collect::<BTreeSet<_>>();
        assert_eq!(
            amounts,
            BATTLE_SCRIPT_TRYSETSPIKES_SPIKES_AMOUNT_U8_DOMAIN
                .into_iter()
                .collect::<BTreeSet<_>>(),
            "attacker side {attacker_side}: complete source u8 spikesAmount domain",
        );
        for case in full.iter().filter(|case| {
            let attacker = case.initial.attacker.expect("full-domain attacker");
            case.initial.battler_sides[attacker.index()] == attacker_side
        }) {
            let attacker = case.initial.attacker.expect("full-domain attacker");
            let amount = case.initial.side_timers[usize::from(attacker_side ^ 1)].spikes_amount;
            let expected_control = if amount == 3 {
                BattleScriptTrysetspikesControl::FailJump
            } else {
                BattleScriptTrysetspikesControl::Advance
            };
            assert_eq!(
                case.controls,
                &[expected_control],
                "{}: exact equality branch",
                case.label
            );
            assert_eq!(
                attacker.as_u8(),
                attacker_side,
                "{}: full domain representative",
                case.label
            );
        }
    }

    let aliases = BATTLE_SCRIPT_TRYSETSPIKES_CASES
        .iter()
        .filter(|case| case.category == "attacker-side-alias-and-boundary-matrix")
        .collect::<Vec<_>>();
    assert_eq!(aliases.len(), 64);
    let observed = aliases
        .iter()
        .map(|case| {
            let attacker = case.initial.attacker.expect("alias attacker");
            let attacker_side = case.initial.battler_sides[attacker.index()];
            let target_amount =
                case.initial.side_timers[usize::from(attacker_side ^ 1)].spikes_amount;
            (attacker.as_u8(), attacker_side, target_amount)
        })
        .collect::<BTreeSet<_>>();
    let expected = BATTLE_SCRIPT_TRYSETSPIKES_ATTACKER_DOMAIN
        .into_iter()
        .flat_map(|attacker| {
            BATTLE_SCRIPT_TRYSETSPIKES_SIDE_DOMAIN
                .into_iter()
                .flat_map(move |attacker_side| {
                    BATTLE_SCRIPT_TRYSETSPIKES_U8_EDGE_DOMAIN
                        .into_iter()
                        .map(move |amount| (attacker, attacker_side, amount))
                })
        })
        .collect::<BTreeSet<_>>();
    assert_eq!(observed, expected);
}

#[test]
fn selector_aliases_full_u32_status_edges_and_side_timer_siblings_are_preserved() {
    let selector_cases = BATTLE_SCRIPT_TRYSETSPIKES_CASES
        .iter()
        .filter(|case| case.category == "complete-attacker-target-effect-fainted-selector-matrix")
        .collect::<Vec<_>>();
    assert_eq!(selector_cases.len(), 500);
    let role_value = |value: Option<BattleScriptTrysetspikesBattler>| {
        value.map_or(-1_i8, |battler| battler.as_u8() as i8)
    };
    let observed_roles = selector_cases
        .iter()
        .map(|case| {
            (
                role_value(case.initial.attacker),
                role_value(case.initial.target),
                role_value(case.initial.effect_battler),
                role_value(case.initial.fainted),
            )
        })
        .collect::<BTreeSet<_>>();
    let expected_roles = (0_i8..4)
        .flat_map(|attacker| {
            (-1_i8..4).flat_map(move |target| {
                (-1_i8..4).flat_map(move |effect_battler| {
                    (-1_i8..4).map(move |fainted| (attacker, target, effect_battler, fainted))
                })
            })
        })
        .collect::<BTreeSet<_>>();
    assert_eq!(observed_roles, expected_roles);
    for case in selector_cases {
        let expected = case.expected.expect("selector case output");
        assert_eq!(
            expected.attacker, case.initial.attacker,
            "{}: attacker preserved",
            case.label
        );
        assert_eq!(
            expected.target, case.initial.target,
            "{}: target preserved",
            case.label
        );
        assert_eq!(
            expected.effect_battler, case.initial.effect_battler,
            "{}: effectBattler preserved",
            case.label,
        );
        assert_eq!(
            expected.fainted, case.initial.fainted,
            "{}: fainted preserved",
            case.label
        );
    }

    let explicit_aliases = BATTLE_SCRIPT_TRYSETSPIKES_CASES
        .iter()
        .filter(|case| case.category == "explicit-selector-alias-permutations")
        .collect::<Vec<_>>();
    assert_eq!(explicit_aliases.len(), 16);
    for battler in BATTLE_SCRIPT_TRYSETSPIKES_ATTACKER_DOMAIN {
        let all_roles = explicit_aliases
            .iter()
            .find(|case| case.label == format!("selector_alias_b{battler}_variant0"))
            .expect("all-role alias vector");
        let expected_battler = BATTLE_SCRIPT_TRYSETSPIKES_BATTLERS[usize::from(battler)];
        assert_eq!(all_roles.initial.attacker, Some(expected_battler));
        assert_eq!(all_roles.initial.target, Some(expected_battler));
        assert_eq!(all_roles.initial.effect_battler, Some(expected_battler));
        assert_eq!(all_roles.initial.fainted, Some(expected_battler));
    }

    let status_cases = BATTLE_SCRIPT_TRYSETSPIKES_CASES
        .iter()
        .filter(|case| case.category == "side-status-u32-edge-pair-matrix")
        .collect::<Vec<_>>();
    assert_eq!(status_cases.len(), 128);
    for attacker_side in BATTLE_SCRIPT_TRYSETSPIKES_SIDE_DOMAIN {
        let observed = status_cases
            .iter()
            .filter(|case| {
                let attacker = case.initial.attacker.expect("status attacker");
                case.initial.battler_sides[attacker.index()] == attacker_side
            })
            .map(|case| {
                (
                    case.initial.side_statuses[usize::from(attacker_side)],
                    case.initial.side_statuses[usize::from(attacker_side ^ 1)],
                )
            })
            .collect::<BTreeSet<_>>();
        let expected = BATTLE_SCRIPT_TRYSETSPIKES_SIDE_STATUS_U32_EDGE_DOMAIN
            .into_iter()
            .flat_map(|own| {
                BATTLE_SCRIPT_TRYSETSPIKES_SIDE_STATUS_U32_EDGE_DOMAIN
                    .into_iter()
                    .map(move |target| (own, target))
            })
            .collect::<BTreeSet<_>>();
        assert_eq!(
            observed, expected,
            "side {attacker_side}: all full-u32 edge pairs"
        );
    }

    let timer_cases = BATTLE_SCRIPT_TRYSETSPIKES_CASES
        .iter()
        .filter(|case| case.category == "side-timer-sibling-u8-edge-preservation")
        .collect::<Vec<_>>();
    assert_eq!(timer_cases.len(), 16);
    for case in timer_cases {
        let output = case.expected.expect("side timer output");
        assert_eq!(
            output.mist_timers, case.initial.mist_timers,
            "{}: mistTimers preserved",
            case.label
        );
        assert_eq!(
            output.attacker, case.initial.attacker,
            "{}: attacker preserved",
            case.label
        );
        assert_eq!(
            output.target, case.initial.target,
            "{}: target preserved",
            case.label
        );
        assert_eq!(
            output.effect_battler, case.initial.effect_battler,
            "{}: effectBattler preserved",
            case.label,
        );
        assert_eq!(
            output.fainted, case.initial.fainted,
            "{}: fainted preserved",
            case.label
        );
    }
}

#[test]
fn prior_pressure_bits_repeated_paths_and_corrupt_wrapping_are_pinned() {
    let pressure_cases = BATTLE_SCRIPT_TRYSETSPIKES_CASES
        .iter()
        .filter(|case| case.category == "complete-per-battler-pressure-prior-bit-matrix")
        .collect::<Vec<_>>();
    assert_eq!(pressure_cases.len(), 16);
    let pack = |bits: [u8; 4]| {
        bits.into_iter()
            .enumerate()
            .fold(0_u8, |word, (index, value)| word | (value << index))
    };
    assert_eq!(
        pressure_cases
            .iter()
            .map(|case| pack(case.initial.pp_not_affected_by_pressure))
            .collect::<BTreeSet<_>>(),
        (0_u8..16).collect::<BTreeSet<_>>(),
        "all four prior PP Pressure bits must be independently covered",
    );

    let repeated_zero = BATTLE_SCRIPT_TRYSETSPIKES_CASES
        .iter()
        .find(|case| {
            case.label
                == "repeated_zero_layers_advances_three_times_then_failjumps_with_pressure_only"
        })
        .expect("zero-layer repeated vector");
    assert_eq!(repeated_zero.applications, 4);
    assert_eq!(
        repeated_zero.controls,
        &[
            BattleScriptTrysetspikesControl::Advance,
            BattleScriptTrysetspikesControl::Advance,
            BattleScriptTrysetspikesControl::Advance,
            BattleScriptTrysetspikesControl::FailJump,
        ],
    );
    let zero_output = repeated_zero.expected.expect("zero-layer output");
    assert_eq!(zero_output.side_timers[1].spikes_amount, 3);
    assert_eq!(zero_output.pp_not_affected_by_pressure[0], 1);

    let repeated_wrap = BATTLE_SCRIPT_TRYSETSPIKES_CASES
        .iter()
        .find(|case| case.label == "repeated_corrupt_255_wraps_and_advances")
        .expect("corrupt wrapping vector");
    assert_eq!(repeated_wrap.applications, 3);
    assert_eq!(
        repeated_wrap.controls,
        &[
            BattleScriptTrysetspikesControl::Advance,
            BattleScriptTrysetspikesControl::Advance,
            BattleScriptTrysetspikesControl::Advance,
        ],
    );
    let wrap_output = repeated_wrap.expected.expect("corrupt wrapping output");
    assert_eq!(wrap_output.side_timers[1].spikes_amount, 2);
    assert_eq!(
        wrap_output.pp_not_affected_by_pressure, repeated_wrap.initial.pp_not_affected_by_pressure,
        "all-success corrupt wrapping path must not set PP exemption",
    );

    let repeated_fail = BATTLE_SCRIPT_TRYSETSPIKES_CASES
        .iter()
        .find(|case| case.label == "repeated_exact_three_failjump_is_pressure_idempotent")
        .expect("exact-three repeated vector");
    assert_eq!(repeated_fail.applications, 2);
    assert_eq!(
        repeated_fail.controls,
        &[
            BattleScriptTrysetspikesControl::FailJump,
            BattleScriptTrysetspikesControl::FailJump,
        ],
    );
    let fail_output = repeated_fail.expected.expect("exact-three output");
    assert_eq!(fail_output.side_timers[0].spikes_amount, 3);
    assert_eq!(fail_output.pp_not_affected_by_pressure[1], 1);

    let two_then_three = BATTLE_SCRIPT_TRYSETSPIKES_CASES
        .iter()
        .find(|case| case.label == "repeated_two_then_three_advances_then_failjumps")
        .expect("two-then-three vector");
    assert_eq!(
        two_then_three.controls,
        &[
            BattleScriptTrysetspikesControl::Advance,
            BattleScriptTrysetspikesControl::FailJump,
        ],
    );
}

#[test]
fn malformed_missing_and_unresolved_errors_follow_canonical_order() {
    let ordered = BATTLE_SCRIPT_TRYSETSPIKES_CASES
        .iter()
        .filter(|case| case.category == "ordered-handler-errors")
        .collect::<Vec<_>>();
    assert_eq!(ordered.len(), 5);
    for label in [
        "malformed_zero_operands_precedes_missing_attacker_and_failure_lookup",
        "malformed_two_operands_precedes_missing_attacker_and_failure_lookup",
        "malformed_width_precedes_missing_attacker_and_failure_lookup",
    ] {
        let case = ordered
            .iter()
            .find(|case| case.label == label)
            .expect("malformed vector");
        assert_eq!(
            case.expected_error,
            Some("Cmd_trysetspikes requires exactly one four-byte failure pointer")
        );
        assert!(case.controls.is_empty());
    }
    let missing = ordered
        .iter()
        .find(|case| {
            case.label == "missing_attacker_precedes_exact_three_unresolved_failure_lookup"
        })
        .expect("missing attacker vector");
    assert_eq!(missing.initial.attacker, None);
    assert_eq!(
        missing.expected_error,
        Some("Battle Script hit-chain command requires a attacker role"),
    );
    let unresolved = ordered
        .iter()
        .find(|case| case.label == "unresolved_failure_target_after_attacker_and_exact_three_check")
        .expect("unresolved target vector");
    assert_eq!(
        unresolved.initial.attacker.map(|value| value.as_u8()),
        Some(0)
    );
    assert_eq!(
        unresolved.expected_error,
        Some(
            "Cmd_trysetspikes unresolved failure target BattleScript_UnresolvedTrysetspikesFailure"
        ),
    );
    assert_eq!(unresolved.instruction.resolved_failure_target, None);

    let skipped = BATTLE_SCRIPT_TRYSETSPIKES_CASES
        .iter()
        .find(|case| case.label == "unresolved_failure_target_not_read_on_nonthree_success")
        .expect("unresolved success-skip vector");
    assert_eq!(skipped.instruction.resolved_failure_target, None);
    assert_eq!(
        skipped.controls,
        &[BattleScriptTrysetspikesControl::Advance]
    );
    assert_eq!(skipped.expected_error, None);
}

