    assert_eq!(BATTLE_SCRIPT_TRYSETSPIKES_BATTLER_COUNT, 4);
    assert_eq!(BATTLE_SCRIPT_TRYSETSPIKES_SIDE_COUNT, 2);
    assert_eq!(BATTLE_SCRIPT_TRYSETSPIKES_OPCODE, 0xb0);
